{
  "name": "是德科技 N90xxB X 系列信号分析仪",
  "name_en": "Keysight N90xxB X-Series Signal Analyzer",
  "manufacturer": "Keysight Technologies",
  "description": "这是一类台式射频信号/频谱分析仪，用于观察和测量信号的频谱分布、功率电平、带宽、杂散、噪声及相关射频特性。它常用于射频与微波实验、通信信号测试、器件表征和频谱扫频测量，并支持分辨率带宽、视频带宽、检波器、输入衰减、参考电平、轨迹读取及部分 IQ 采集相关功能。",
  "description_en": "This is a benchtop RF signal/spectrum analyzer used to view and measure signal spectra, power levels, bandwidth, spurs, noise, and related RF characteristics. It is commonly used in RF and microwave labs for communication signal testing, device characterization, and swept spectrum measurements, with support for resolution bandwidth, video bandwidth, detector selection, input attenuation, reference level control, trace readout, and some IQ capture-related functions.",
  "tag_hints": [
    "RF spectrum analysis",
    "signal analyzer",
    "swept spectrum measurement",
    "resolution bandwidth",
    "video bandwidth",
    "trace acquisition",
    "IQ capture",
    "microwave test"
  ],
  "actions": [
    {
      "action_name": "auto-clear_spectrum_state",
      "description": "清除频谱校正状态。",
      "description_en": "Clear the spectrum correction state."
    },
    {
      "action_name": "auto-select",
      "description": "获取或设置当前测量/工作模式。",
      "description_en": "Get or set the current measurement/operating mode."
    },
    {
      "action_name": "auto-sweep_points",
      "description": "获取或设置扫频点数。",
      "description_en": "Get or set the number of sweep points."
    },
    {
      "action_name": "auto-sweep_points_max",
      "description": "获取最大扫频点数。",
      "description_en": "Get the maximum number of sweep points."
    },
    {
      "action_name": "auto-sweep_time",
      "description": "获取或设置扫频时间。",
      "description_en": "Get or set the sweep time."
    },
    {
      "action_name": "auto-reference_output",
      "description": "获取或设置 10 MHz 参考输出状态。",
      "description_en": "Get or set the 10 MHz reference output state."
    },
    {
      "action_name": "auto-reference_level",
      "description": "获取或设置参考电平。",
      "description_en": "Get or set the reference level."
    },
    {
      "action_name": "auto-reference_level_offset",
      "description": "获取或设置参考电平偏置。",
      "description_en": "Get or set the reference level offset."
    },
    {
      "action_name": "auto-reference_level_offset_state",
      "description": "获取或设置参考电平偏置启用状态。",
      "description_en": "Get or set the reference level offset enable state."
    },
    {
      "action_name": "auto-PDIVision",
      "description": "获取显示纵轴正向每格刻度。",
      "description_en": "Get the positive per-division scale of the display vertical axis."
    },
    {
      "action_name": "auto-NDIVision",
      "description": "获取显示纵轴负向每格刻度。",
      "description_en": "Get the negative per-division scale of the display vertical axis."
    },
    {
      "action_name": "auto-view_range",
      "description": "获取当前显示范围。",
      "description_en": "Get the current display range."
    },
    {
      "action_name": "auto-resolution_bandwidths",
      "description": "获取可用的分辨率带宽列表。",
      "description_en": "Get the list of available resolution bandwidths."
    },
    {
      "action_name": "auto-resolution_bandwidth",
      "description": "获取或设置分辨率带宽。",
      "description_en": "Get or set the resolution bandwidth."
    },
    {
      "action_name": "auto-video_bandwidth",
      "description": "获取或设置视频带宽。",
      "description_en": "Get or set the video bandwidth."
    },
    {
      "action_name": "auto-unit_power",
      "description": "获取或设置功率单位。",
      "description_en": "Get or set the power unit."
    },
    {
      "action_name": "auto-detector",
      "description": "获取或设置检波器模式。",
      "description_en": "Get or set the detector mode."
    },
    {
      "action_name": "auto-input_attenuator",
      "description": "获取或设置输入衰减。",
      "description_en": "Get or set the input attenuation."
    },
    {
      "action_name": "auto-continuous",
      "description": "获取或设置连续扫频状态。",
      "description_en": "Get or set the continuous sweep state."
    },
    {
      "action_name": "auto-input_attenuator_auto",
      "description": "获取或设置输入自动衰减状态。",
      "description_en": "Get or set the automatic input attenuation state."
    },
    {
      "action_name": "auto-trace_type",
      "description": "获取或设置轨迹类型。",
      "description_en": "Get or set the trace type."
    },
    {
      "action_name": "auto-feed",
      "description": "获取或设置信号输入路径/源。",
      "description_en": "Get or set the signal input path/source."
    },
    {
      "action_name": "auto-external_gain",
      "description": "获取或设置外部增益校正。",
      "description_en": "Get or set the external gain correction."
    },
    {
      "action_name": "auto-screenshot",
      "description": "采集屏幕截图。",
      "description_en": "Capture a screenshot."
    },
    {
      "action_name": "auto-trace_data",
      "description": "读取当前轨迹数据。",
      "description_en": "Read the current trace data."
    },
    {
      "action_name": "auto-trace",
      "description": "读取轨迹数据。",
      "description_en": "Read trace data."
    },
    {
      "action_name": "auto-trace_iq_fcap_context",
      "description": "读取 IQ 快速采集上下文信息。",
      "description_en": "Read the IQ fast-capture context information."
    },
    {
      "action_name": "auto-trace_iq_fcap",
      "description": "读取 IQ 快速采集数据。",
      "description_en": "Read IQ fast-capture data."
    },
    {
      "action_name": "auto-trace_sa",
      "description": "读取频谱分析轨迹及相关配置数据。",
      "description_en": "Read spectrum-analyzer trace data and related configuration."
    }
  ]
}

